insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$diamantina$q$, $q$https://www.diamantina.mg.gov.br/portal/leis_decretos/7556/ (Lei 3.693/2011; PDF https://www.diamantina.mg.gov.br/publicos/015e88b890da2a69fcd660bbb6a51bdb.pdf) ; https://www.diariomunicipal.com.br/amm-mg/materia/85731498 (Decreto 259/2025, PMUS)$q$, $q$Atos oficiais de Diamantina: domínio público (Lei 9.610/1998 art. 8º IV). Polígono aproximado do Centro Histórico derivado do OpenStreetMap (cruzamentos do art. 17; ODbL 1.0, © colaboradores do OSM).$q$, 2, $q$Lei 3.693/2011, art. 9º: caminhões acima de 7 t e/ou 6,50 m, truck, cavalo mecânico, carretas e bitrem proibidos no Centro Histórico (24 h). Confirmada em 2025 pelo PMUS (Dec. 259/2025, art. 62, VII). Polígono aproximado pelos 15 pontos de placa do art. 17.$q$);
